CREATE PROCEDURE [bud].[jsRejectBudget]      @docId INT = 5948,      @company INT = 1,      @userId INT = 79,      @remarks NVARCHAR(MAX) = 'R',      @action NVARCHAR(20) = 'Reject'   AS  BEGIN      SET NOCOUNT ON;        DECLARE @Message NVARCHAR(4000);        BEGIN TRY          BEGIN TRANSACTION;            DECLARE @templateId INT;          DECLARE @totalStages INT;          DECLARE @currentStage INT;          DECLARE @rejectionRequired INT;          DECLARE @rejectedCount INT;          DECLARE @existingStatus NVARCHAR(50) = 'None';          DECLARE @currentStageId INT;          DECLARE @userStage INT;          DECLARE @userStageId INT;          DECLARE @previousStage INT;          DECLARE @previousStageId INT;          DECLARE @currentStageActions INT;          DECLARE @newDescription NVARCHAR(MAX);            -- Get budget details          SELECT               @templateId = templateId,              @totalStages = totalStage,              @currentStage = currentSatge          FROM bud.jsDocEntry          WHERE id = @docId                    -- If budget not found, throw error          IF @templateId IS NULL          BEGIN              THROW 50001, 'Budget not found with the specified parameters', 1;          END                    -- Get Current Stage ID          SELECT @currentStageId = stageId           FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @currentStage;                    -- Get Previous Stage ID          SET @previousStage = @currentStage - 1;          SELECT @previousStageId = stageId           FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @previousStage;                    -- Determine which stage this user belongs to          SELECT TOP 1 @userStage = jst.priority, @userStageId = jst.stageId          FROM jsUserStage us          JOIN jsStageTemplate jst ON us.stageId = jst.stageId          WHERE us.userId = @userId          AND jst.templateId = @templateId          ORDER BY jst.priority;                    -- Check if user belongs to any stage in this template          IF @userStage IS NULL          BEGIN              THROW 50002, 'User is not assigned to any stage in this budget approval workflow', 1;          END                    -- Check if any actions exist in the current stage          SELECT @currentStageActions = COUNT(*)           FROM bud.jsBudgetStatusWorkflow           WHERE docId = @docId           AND stageId = @currentStageId;                    -- Check if the user has already taken action          SELECT TOP 1 @existingStatus = status           FROM bud.jsBudgetStatusWorkflow          WHERE docId = @docId           AND stageId = @userStageId          AND userId = @userId           ORDER BY createdOn DESC;            -- REJECT LOGIC          IF @action = 'Reject'          BEGIN              -- Prevent duplicate rejections in the same stage              IF @existingStatus = 'R' AND @userStage = @currentStage              BEGIN                  THROW 50021, 'User has already rejected this budget.', 1;              END                            -- Check if user is authorized (in current stage or previous if no actions taken)              IF NOT EXISTS (                  SELECT 1                   FROM jsStageTemplate                  WHERE templateId = @templateId                     AND (stageId = @currentStageId OR (@currentStageActions = 0 AND stageId = @previousStageId))                    AND EXISTS (SELECT 1 FROM jsUserStage WHERE stageId = jsStageTemplate.stageId AND userId = @userId)              )              BEGIN                  THROW 50006, 'User is not authorized to reject this budget at the current stage.', 1;              END                            -- HANDLE PREVIOUSLY APPROVED USER WHO WANTS TO CHANGE TO REJECT              IF @existingStatus = 'A' AND @userStage < @currentStage AND @currentStageActions = 0              BEGIN                  -- Update the budget status to move back to this user's stage                  UPDATE bud.jsDocEntry                  SET currentSatge = @userStage,                      currentStageId = @userStageId                  WHERE id = @docId                                    -- Sync to HANA                 -- EXEC [bud].[jsSyncBudgetStatusToHana]                  --     @docId, @company, 'P', @userStage;                                    SET @Message = 'Budget moved back to previous stage for rejection';              END                -- Insert new rejection entry if no previous record exists,              -- or update the record if the user initially approved              IF @existingStatus IS NULL OR @existingStatus = 'None'              BEGIN                  -- Insert local record                  INSERT INTO bud.jsBudgetStatusWorkflow                       (docId, status, stageId, templateId, userId, createdOn, description)                  VALUES                       (@docId, 'R', @userStageId, @templateId, @userId, GETDATE(), @remarks);                                    -- Sync to HANA                  --EXEC [bud].[jsSyncBudgetWorkflowToHana]                   --    @docId, @company, 'R', @userStageId, @templateId, @userId, @remarks, 1;                                        -- Update HANA draft approval when any user rejects                  EXEC [bud].[jsSyncBudgetToHanaDraftApproval]                      @docId, @company, 'R', @userId, @remarks;              END              ELSE              BEGIN                  -- Update local record                  UPDATE bud.jsBudgetStatusWorkflow                  SET status = 'R',                       description = @remarks,                       createdOn = GETDATE()                   WHERE docId = @docId                   AND stageId = @userStageId                   AND userId = @userId;                                    -- Sync to HANA                  --EXEC [bud].[jsSyncBudgetWorkflowToHana]                   --    @docId, @company, 'R', @userStageId, @templateId, @userId, @remarks, 0;                                        -- Update HANA draft approval when any user rejects                  EXEC [bud].[jsSyncBudgetToHanaDraftApproval]                      @docId, @company, 'R', @userId, @remarks;              END                            -- Re-evaluate the current stage (which may have changed)              SELECT @currentStage = currentSatge              FROM bud.jsDocEntry              WHERE id = @docId                            -- Get updated Current Stage ID              SELECT @currentStageId = stageId               FROM jsStageTemplate              WHERE templateId = @templateId AND priority = @currentStage;                -- Determine the number of rejections required for this stage              SELECT @rejectionRequired = rejection              FROM jsStage              INNER JOIN jsRejectionCount ON jsStage.approvalId = jsRejectionCount.id              WHERE jsStage.id = @currentStageId;                -- Count how many rejections have been made in this stage              SELECT @rejectedCount = COUNT(*)               FROM bud.jsBudgetStatusWorkflow                WHERE docId = @docId              AND stageId = @currentStageId               AND status = 'R';                -- If the required number of rejections is met, proceed to mark the budget as Rejected              IF @rejectedCount >= @rejectionRequired              BEGIN                  DECLARE @status NVARCHAR(100);                    -- Call the procedure that saves data in SAP                  -- EXEC [jsSaveDataInSAP] @docEntry, @userId, @company, 'R', @status OUTPUT;                             -- If data already exists in SAP, rollback all changes and exit                  IF @status = 'Data is in SAP for DocEntry'                  BEGIN                      THROW 50010, 'Data is in SAP for DocEntry. Rolling back all transactions.', 1;                  END                  ELSE                  BEGIN                      -- Update local status                      UPDATE bud.jsDocEntry                       SET status = 'R'                      WHERE id = @docId                                            -- Keep this call as a fallback                      EXEC [bud].[jsSyncBudgetToHanaDraftApproval]                          @docId, @company, 'R', @userId, @remarks;                        -- Sync to HANA Budget Status                      --EXEC [bud].[jsSyncBudgetStatusToHana]                       --    @docId, @company, 'R', NULL;                                                         SET @Message = 'Budget rejected successfully';                  END              END              ELSE              BEGIN                  -- Use sp_executesql to safely concatenate strings                  EXEC sp_executesql                       N'SELECT @Result = ''Not enough rejections to mark the budget as rejected. Current: '' + CAST(@CurrentCount AS NVARCHAR) + '', Required: '' + CAST(@RequiredCount AS NVARCHAR)',                      N'@CurrentCount INT, @RequiredCount INT, @Result NVARCHAR(4000) OUTPUT',                      @rejectedCount, @rejectionRequired, @Message OUTPUT;              END          END          -- CANCEL REJECTION LOGIC          ELSE IF @action = 'Cancel'          BEGIN              -- Get existing status for this user              SELECT TOP 1 @existingStatus = status               FROM bud.jsBudgetStatusWorkflow              WHERE docId = @docId              AND userId = @userId               ORDER BY createdOn DESC;                            -- Check if the user previously rejected              IF @existingStatus != 'R'              BEGIN                  THROW 50011, 'You cannot cancel a rejection you never made.', 1;              END                            -- Check if actions have been taken in the current stage              IF @currentStageActions > 0 AND @userStage < @currentStage              BEGIN                  THROW 50007, 'Cannot cancel rejection because actions have already been taken in the current stage', 1;              END                            -- Get existing description              SELECT @newDescription = ISNULL(description, '')               FROM bud.jsBudgetStatusWorkflow              WHERE docId = @docId              AND stageId = @userStageId              AND userId = @userId;                            -- Use sp_executesql to safely concatenate strings              EXEC sp_executesql                   N'SELECT @Result = @Existing + '' | Cancelled: '' + @RemarkText',                  N'@Existing NVARCHAR(MAX), @RemarkText NVARCHAR(MAX), @Result NVARCHAR(MAX) OUTPUT',                  @newDescription, @remarks, @newDescription OUTPUT;                            -- Allow the user to cancel their rejection              UPDATE bud.jsBudgetStatusWorkflow              SET status = 'Cancelled',                   description = @newDescription,                   createdOn = GETDATE()              WHERE docId = @docId               AND stageId = @userStageId              AND userId = @userId              AND status = 'R';                            -- Sync to HANA              --EXEC [bud].[jsSyncBudgetWorkflowToHana]               --    @docId, @company, 'Cancelled', @userStageId, @templateId, @userId,               --    @newDescription, 0;                            -- If user from previous stage, move budget back to that stage              IF @userStage < @currentStage              BEGIN                  UPDATE bud.jsDocEntry                  SET currentSatge = @userStage,                      currentStageId = @userStageId,                      status = 'P'                  WHERE id = @docId                                    -- Sync to HANA                  --EXEC [bud].[jsSyncBudgetStatusToHana]                   --    @docId, @company, 'P', @userStage;                                    SET @Message = 'Rejection cancelled and budget returned to previous stage';              END              ELSE              BEGIN                  SET @Message = 'Rejection cancelled in current stage';              END          END          ELSE          BEGIN              THROW 50009, 'Invalid action specified. Use "Reject" or "Cancel"', 1;          END            COMMIT TRANSACTION;                    -- Return the message as part of the result set          SELECT @Message AS ResultMessage;      END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;                          DECLARE @ErrorMessage NVARCHAR(4000),                  @ErrorSeverity INT,                  @ErrorState INT;            SELECT               @ErrorMessage = ERROR_MESSAGE(),              @ErrorSeverity = ERROR_SEVERITY(),              @ErrorState = ERROR_STATE();            RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);      END CATCH  END      --select * from bud.jsDocEntry  --select * from bud.jsBudgetStatusWorkflow
